INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1150, 'client', '/ˈklaɪənt/', 'noun', '{"zh-TW":["客戶"],"en":["a person or organization using professional services"]}', '{"root":{"text":"cli","meaning":"lean/depend (依靠)"},"suffix":{"text":"-ent","meaning":"person (人)"},"logic":"依靠服務的人，即「客戶」。"}', 'client base / client relationship / potential client', '[{"en":"We aim to build long-term relationships with our clients.","zh-TW":"我們旨在與客戶建立長期關係。"},{"en":"The firm serves over 200 corporate clients.","zh-TW":"該公司服務超過200家企業客戶。"}]', '{"noun":"clientele"}', NULL, 2, 1150, 289),
(1151, 'client acquisition', '/ˈklaɪənt ˌækwɪˈzɪʃən/', 'noun', '{"zh-TW":["客戶獲取；客戶開發"],"en":["the process of gaining new clients or customers for a business"]}', NULL, 'focus on client acquisition / client acquisition strategy', '[{"en":"Client acquisition costs decreased after optimizing the sales funnel.","zh-TW":"優化銷售漏斗後客戶獲取成本降低了。"},{"en":"A successful client acquisition strategy combines marketing and outreach.","zh-TW":"成功的客戶獲取策略結合了行銷和外聯活動。"}]', NULL, NULL, 5, 1151, NULL),
(1152, 'client base', '/ˈklaɪənt beɪs/', 'noun', '{"zh-TW":["客戶群；客戶基礎"],"en":["the group of regular customers a business serves"]}', NULL, 'expand the client base / loyal client base', '[{"en":"The company grew its client base from 50 to 200 in two years.","zh-TW":"公司在兩年內將客戶群從50家增長到了200家。"},{"en":"A diverse client base protects against revenue concentration risk.","zh-TW":"多元化的客戶群防止了收入集中風險。"}]', NULL, NULL, 4, 1152, NULL),
(1153, 'client relationship', '/ˈklaɪənt rɪˈleɪʃənʃɪp/', 'noun', '{"zh-TW":["客戶關係"],"en":["the ongoing professional interaction between a service provider and their client"]}', NULL, 'build client relationships / manage client relationships', '[{"en":"Building strong client relationships is essential for account retention.","zh-TW":"建立強大的客戶關係對帳戶保留至關重要。"},{"en":"Regular check-ins are key to nurturing long-term client relationships.","zh-TW":"定期拜訪是培養長期客戶關係的關鍵。"}]', NULL, NULL, 5, 1153, NULL),
(1154, 'clientele', '/ˌkliːɒnˈtɛl/', 'noun', '{"zh-TW":["客戶群"],"en":["all the clients of a business"]}', NULL, 'loyal clientele / build a clientele', '[{"en":"We have a loyal clientele.","zh-TW":"我們有一群忠實的客戶。"},{"en":"The spa attracts a high-end clientele.","zh-TW":"這間SPA吸引高端客群。"}]', '{"noun":"clientele"}', NULL, 3, 1154, 760),
(1155, 'cliff vesting', '/klɪf ˈvestɪŋ/', 'noun', '{"zh-TW":["懸崖式歸屬"],"en":["a vesting structure where no equity is earned until a specific date"]}', NULL, 'one-year cliff / cliff vesting period / after the cliff', '[{"en":"Employees receive no shares until the one-year cliff vesting date.","zh-TW":"員工在一年懸崖式歸屬日期前不會獲得任何股票。"},{"en":"Cliff vesting encourages employees to stay through the initial period.","zh-TW":"懸崖式歸屬鼓勵員工度過初始期。"}]', NULL, NULL, 5, 1155, NULL),
(1156, 'climate', '/ˈklaɪmɪt/', 'noun', '{"zh-TW":["氣候"],"en":["the usual weather conditions in an area"]}', '{"root":{"text":"clima","meaning":"slope/region (地帶)"},"logic":"源自希臘語 klima（傾斜），指不同地帶的天氣型態。"}', 'climate change / tropical climate', '[{"en":"Climate change is a global concern.","zh-TW":"氣候變遷是全球關注的議題。"},{"en":"This region has a mild climate.","zh-TW":"這個地區氣候溫和。"}]', '{"adjective":"climatic"}', NULL, 3, 1156, NULL),
(1157, 'climate change', '/ˈklaɪmɪt tʃeɪndʒ/', 'noun', '{"zh-TW":["氣候變遷"],"en":["long-term changes in global temperatures and weather patterns"]}', NULL, 'address climate change / climate change impact', '[{"en":"Climate change is causing more frequent extreme weather events.","zh-TW":"氣候變遷正在導致更頻繁的極端天氣事件。"},{"en":"International cooperation is needed to combat climate change.","zh-TW":"需要國際合作來應對氣候變遷。"}]', NULL, NULL, 5, 1157, NULL),
(1158, 'climate resilience', '/ˈklaɪmɪt rɪˈzɪliəns/', 'noun', '{"zh-TW":["氣候韌性"],"en":["the ability to anticipate, prepare for, and recover from climate disruptions"]}', NULL, 'build climate resilience / improve climate resilience / climate resilience strategy', '[{"en":"Coastal cities are investing in climate resilience infrastructure.","zh-TW":"沿海城市正在投資氣候韌性基礎設施。"},{"en":"Climate resilience planning must consider both mitigation and adaptation.","zh-TW":"氣候韌性規劃必須考慮減緩和適應兩個方面。"}]', '{"adjective":"climate-resilient"}', NULL, 5, 1158, NULL),
(1159, 'climb', '/klaɪm/', 'verb', '{"zh-TW":["爬；攀登"],"en":["to go up to the top of something"]}', NULL, 'climb a mountain / climb the ladder', '[{"en":"We climbed the mountain in three hours.","zh-TW":"我們花了三個小時爬上那座山。"},{"en":"She climbed the career ladder quickly.","zh-TW":"她很快就步步高升了。"}]', '{"noun":"climb","noun2":"climber"}', NULL, 2, 1159, NULL),
(1160, 'clinic', '/ˈklɪnɪk/', 'noun', '{"zh-TW":["診所；診療室"],"en":["a place where people receive medical treatment"]}', NULL, 'visit a clinic / outpatient clinic', '[{"en":"She went to the clinic for a routine checkup.","zh-TW":"她去診所進行例行健康檢查。"},{"en":"The clinic is open from Monday to Saturday.","zh-TW":"診所從週一到週六開放。"}]', '{"adjective":"clinical","adverb":"clinically"}', NULL, 2, 1160, NULL),
(1161, 'clinical trial phases', '/ˈklɪnɪkəl ˈtraɪəl feɪzɪz/', 'noun', '{"zh-TW":["臨床試驗階段"],"en":["the sequential stages of testing a new drug or treatment"]}', NULL, 'phase one to three clinical trial phases / complete clinical trial phases / early clinical trial phases', '[{"en":"A new drug must pass through multiple clinical trial phases before approval.","zh-TW":"新藥在獲批之前必須通過多個臨床試驗階段。"},{"en":"Phase three clinical trials test efficacy in large populations.","zh-TW":"第三階段臨床試驗在大規模人群中測試療效。"}]', NULL, NULL, 5, 1161, NULL),
(1162, 'clock', '/klɒk/', 'noun', '{"zh-TW":["時鐘"],"en":["a device that shows the time"]}', NULL, 'around the clock / alarm clock', '[{"en":"The clock on the wall says three.","zh-TW":"牆上的時鐘顯示三點。"},{"en":"They work around the clock.","zh-TW":"他們全天候工作。"}]', NULL, NULL, 2, 1162, NULL),
(1163, 'close', '/kloʊz/', 'verb', '{"zh-TW":["【主要意義-動詞/形容詞】關閉；近的","【次要意義-形容詞】悶熱的；通風不良的","【次要意義-形容詞】吝嗇的；小氣的","【次要意義-名詞】結尾；終結"],"en":["[primary] to shut; near in distance or relationship","[secondary - adjective] uncomfortably warm and lacking fresh air","[secondary - adjective] unwilling to spend money; stingy","[secondary - noun] the end or conclusion of something"]}', NULL, 'close call / a close shave / close-fisted / at the close of', '[{"en":"It was close in the meeting room with all the windows shut.","zh-TW":"所有窗戶都關著，會議室裡悶熱難受。"},{"en":"At the close of trading, the index had risen by 2%.","zh-TW":"交易結束時，指數上漲了2%。"},{"en":"The vote was extremely close, with only three votes separating the candidates.","zh-TW":"投票結果極為接近，兩位候選人僅差三票。"}]', '{"noun":"closure","adjective":"closely"}', 'close 作形容詞表「悶熱的」（天氣），名詞 close 表「結尾/收盤」（at the close of business），是 TOEIC 商業新聞和天氣描述中容易混淆的用法。', 2, 1163, NULL),
(1164, 'close a deal', '/kloʊz ə diːl/', 'verb', '{"zh-TW":["完成交易；成交"],"en":["to finalize an agreement or sale"]}', NULL, 'close the deal / close a big deal', '[{"en":"The sales rep successfully closed a deal worth 500000 dollars.","zh-TW":"銷售代表成功完成了一筆價值50萬美元的交易。"},{"en":"The negotiation team closed the deal after three rounds of talks.","zh-TW":"談判團隊在三輪談判後完成了交易。"}]', NULL, NULL, 4, 1164, NULL),
(1165, 'close of business', '/kloʊz əv ˈbɪznɪs/', 'noun', '{"zh-TW":["業務截止時間；下班時間"],"en":["the end of the business day, typically 5 or 6 PM"]}', NULL, 'submit by close of business / deadline is close of business', '[{"en":"Please send the report by close of business Friday.","zh-TW":"請在週五下班時間前發送報告。"},{"en":"The decision must be finalized by close of business today.","zh-TW":"決定必須在今天下班時間前敲定。"}]', NULL, NULL, 5, 1165, NULL),
(1166, 'closeout', '/ˈkloʊzaʊt/', 'noun', '{"zh-TW":["項目收尾；結案"],"en":["the formal completion and documentation of a project"]}', NULL, 'project closeout / closeout report / closeout meeting', '[{"en":"The closeout report summarized key achievements and lessons learned.","zh-TW":"結案報告總結了主要成就和經驗教訓。"},{"en":"A formal closeout meeting was held with all project stakeholders.","zh-TW":"與所有項目利益相關者舉行了正式結案會議。"}]', '{"verb":"close out"}', NULL, 3, 1166, NULL),
(1167, 'closing', '/ˈkloʊzɪŋ/', 'noun', '{"zh-TW":["結案；成交；交割"],"en":["the final step in completing a business transaction or property sale"]}', NULL, 'deal closing / closing date / closing documents / closing costs', '[{"en":"The closing of the acquisition was completed last week.","zh-TW":"收購的交割於上週完成。"},{"en":"Closing costs for the property included legal fees and stamp duty.","zh-TW":"房產的交割費用包括法律費用和印花稅。"}]', '{"verb":"close","adjective":"closed"}', NULL, 3, 1167, NULL),
(1168, 'closing balance', '/ˈkloʊzɪŋ ˈbæləns/', 'noun', '{"zh-TW":["期末餘額"],"en":["the amount in an account at the end of an accounting period"]}', NULL, 'calculate closing balance / check closing balance', '[{"en":"The closing balance of the account was 15000 dollars.","zh-TW":"帳戶的期末餘額為15000美元。"},{"en":"The closing balance is carried forward as the opening balance.","zh-TW":"期末餘額結轉為下期期初餘額。"}]', '{"opposite":"opening balance"}', NULL, 5, 1168, NULL),
(1169, 'closing costs', '/ˈkloʊzɪŋ kɒsts/', 'noun', '{"zh-TW":["交割費用；過戶費用"],"en":["fees and expenses incurred to complete a property or financial transaction"]}', NULL, 'cover closing costs / closing costs breakdown', '[{"en":"Closing costs for the property purchase totaled 2% of the sale price.","zh-TW":"房產購買的交割費用共計銷售價格的2%。"},{"en":"The buyer negotiated for the seller to cover closing costs.","zh-TW":"買方談判讓賣方承擔交割費用。"}]', NULL, NULL, 5, 1169, NULL),
(1170, 'closing date', '/ˈkloʊzɪŋ deɪt/', 'noun', '{"zh-TW":["截止日期；成交日期"],"en":["the final date for submitting applications or completing a transaction"]}', NULL, 'meet the closing date / application closing date', '[{"en":"The closing date for the tender is 31 January.","zh-TW":"招標的截止日期為1月31日。"},{"en":"All documentation must be received by the closing date.","zh-TW":"所有文件必須在截止日期前收到。"}]', NULL, NULL, 4, 1170, NULL),
(1171, 'closing entry', '/ˈkloʊzɪŋ ˈentri/', 'noun', '{"zh-TW":["結帳分錄"],"en":["an accounting entry that closes temporary accounts to retained earnings at period end"]}', NULL, 'post closing entries / closing entry preparation', '[{"en":"Closing entries reset temporary accounts to zero for the next period.","zh-TW":"結帳分錄將臨時帳戶重置為零以準備下一期。"},{"en":"The closing entry transferred net income to the retained earnings account.","zh-TW":"結帳分錄將淨利潤轉入留存收益帳戶。"}]', NULL, NULL, 5, 1171, NULL),
(1172, 'closing price', '/ˈkloʊzɪŋ praɪs/', 'noun', '{"zh-TW":["收盤價"],"en":["the final price at which a security trades at the end of the trading day"]}', NULL, 'record closing price / analyze the closing price', '[{"en":"The stock''s closing price rose by 3% on strong earnings news.","zh-TW":"受強勁盈利消息影響，股票收盤價上漲了3%。"},{"en":"Investors track the closing price to assess daily market performance.","zh-TW":"投資者追蹤收盤價以評估每日市場表現。"}]', NULL, NULL, 5, 1172, NULL),
(1173, 'cloth', '/klɒθ/', 'noun', '{"zh-TW":["布；布料"],"en":["material made by weaving"]}', NULL, 'table cloth / cloth bag', '[{"en":"Wipe it with a damp cloth.","zh-TW":"用濕布擦拭。"},{"en":"The table cloth is stained.","zh-TW":"桌布髒了。"}]', '{"noun2":"clothing","verb":"clothe"}', NULL, 2, 1173, NULL),
(1174, 'cloud', '/klaʊd/', 'noun', '{"zh-TW":["雲；雲端"],"en":["a white or grey mass in the sky"]}', NULL, 'cloud computing / on cloud nine', '[{"en":"Dark clouds gathered in the sky.","zh-TW":"烏雲密布。"},{"en":"She was on cloud nine after the news.","zh-TW":"聽到消息後她高興極了。"}]', '{"adjective":"cloudy"}', NULL, 2, 1174, NULL),
(1175, 'cloud computing', '/klaʊd kəmˈpjuːtɪŋ/', 'noun', '{"zh-TW":["雲端運算"],"en":["delivering computing services over the internet on a pay-as-you-go basis"]}', NULL, 'cloud computing platform / move to cloud computing / cloud computing benefits', '[{"en":"Cloud computing enabled the startup to scale without heavy infrastructure investment.","zh-TW":"雲端運算使新創公司能夠在不大量基礎設施投資的情況下擴展。"},{"en":"Security is a top concern when adopting cloud computing.","zh-TW":"採用雲端運算時，安全性是首要關注點。"}]', '{"adjective":"cloud-based","noun":"cloud"}', NULL, 5, 1175, NULL),
(1176, 'cloud storage', '/klaʊd ˈstɔːrɪdʒ/', 'noun', '{"zh-TW":["雲端儲存"],"en":["storing data on remote servers accessible via the internet"]}', NULL, 'use cloud storage / migrate to cloud storage', '[{"en":"The company migrated all documents to cloud storage for remote access.","zh-TW":"公司將所有文件遷移到雲端儲存以便遠程存取。"},{"en":"Cloud storage reduces the need for physical server infrastructure.","zh-TW":"雲端儲存減少了對物理伺服器基礎設施的需求。"}]', NULL, NULL, 5, 1176, NULL),
(1177, 'cloud-native', '/klaʊd ˈneɪtɪv/', 'adjective', '{"zh-TW":["雲端原生的"],"en":["designed specifically to take advantage of cloud computing architectures"]}', NULL, 'cloud-native application / cloud-native architecture / cloud-native development', '[{"en":"Cloud-native applications are built to scale dynamically in the cloud.","zh-TW":"雲端原生應用程式是為在雲端動態擴展而構建的。"},{"en":"The team refactored the legacy system into a cloud-native microservices architecture.","zh-TW":"團隊將遺留系統重構為雲端原生微服務架構。"}]', NULL, NULL, 4, 1177, NULL),
(1178, 'club', '/klʌb/', 'noun', '{"zh-TW":["俱樂部；社團"],"en":["a group organized for a shared activity"]}', NULL, 'night club / book club', '[{"en":"She joined the tennis club.","zh-TW":"她加入了網球俱樂部。"},{"en":"The club meets every Friday.","zh-TW":"社團每週五聚會。"}]', NULL, NULL, 1, 1178, NULL),
(1179, 'club floor', '/klʌb flɔːr/', 'noun', '{"zh-TW":["行政樓層；俱樂部樓層"],"en":["a hotel floor offering premium services and a private lounge"]}', NULL, 'stay on the club floor / club floor access', '[{"en":"Club floor guests have access to a private lounge and breakfast.","zh-TW":"行政樓層賓客可進入私人休息室和享用早餐。"},{"en":"Upgrading to the club floor includes exclusive evening cocktails.","zh-TW":"升級到行政樓層包含專屬的傍晚雞尾酒時光。"}]', NULL, NULL, 4, 1179, NULL),
(1180, 'CMO', '/ˌsiː em ˈoʊ/', 'noun', '{"zh-TW":["行銷長；首席行銷官"],"en":["chief marketing officer; the executive leading marketing strategy"]}', NULL, 'CMO responsibilities / appoint a CMO', '[{"en":"The CMO launched a bold new brand campaign to revitalize sales.","zh-TW":"行銷長推出了大膽的新品牌活動以振興銷售。"},{"en":"The CMO aligned the marketing strategy with corporate growth goals.","zh-TW":"行銷長將行銷策略與公司增長目標保持一致。"}]', '{"full form":"chief marketing officer"}', NULL, 1, 1180, NULL),
(1181, 'co-branding', '/ˌkoʊ ˈbrændɪŋ/', 'noun', '{"zh-TW":["聯合品牌；共同品牌"],"en":["a strategy where two companies jointly market their products together"]}', NULL, 'launch a co-branding campaign / co-branding partnership', '[{"en":"The airline and hotel group launched a co-branding loyalty program.","zh-TW":"航空公司和酒店集團推出了聯合品牌忠誠計劃。"},{"en":"Co-branding increases exposure for both partners simultaneously.","zh-TW":"聯合品牌同時增加了雙方合作夥伴的曝光度。"}]', NULL, NULL, 4, 1181, NULL),
(1182, 'co-founder', '/ˈkoʊ faʊndər/', 'noun', '{"zh-TW":["共同創辦人"],"en":["one of two or more people who establish a company together"]}', NULL, 'company co-founder / startup co-founder', '[{"en":"The co-founders met in graduate school before starting the company.","zh-TW":"共同創辦人在研究所時相識，之後共同創立了公司。"},{"en":"The co-founder stepped down as chairman after the IPO.","zh-TW":"共同創辦人在首次公開募股後卸任主席。"}]', NULL, NULL, 4, 1182, NULL),
(1183, 'co-insurance', '/ˌkəʊ ɪnˈʃʊərəns/', 'noun', '{"zh-TW":["共同保險；自付比例"],"en":["the percentage of costs shared by insurer and insured"]}', NULL, 'co-insurance rate / co-insurance clause', '[{"en":"After the deductible, you pay 20% as co-insurance.","zh-TW":"達到免賠額後，您支付20%作為自付比例。"},{"en":"The co-insurance provision is outlined in your policy.","zh-TW":"共同保險條款已在您的保單中列明。"}]', NULL, NULL, 4, 1183, NULL),
(1184, 'co-invest', '/ˌkoʊ ɪnˈvest/', 'verb', '{"zh-TW":["共同投資"],"en":["to invest jointly with another party in a project or company"]}', NULL, 'co-invest in a venture / co-investment agreement', '[{"en":"The two funds agreed to co-invest in the renewable energy project.","zh-TW":"兩隻基金同意共同投資可再生能源項目。"},{"en":"Co-investing allows each party to spread financial risk.","zh-TW":"共同投資使各方能夠分散財務風險。"}]', '{"noun":"co-investment","noun2":"co-investor"}', NULL, 3, 1184, NULL),
(1185, 'co-investment', '/ˌkoʊ ɪnˈvestmənt/', 'noun', '{"zh-TW":["共同投資；聯合投資"],"en":["investing alongside another party in the same venture or project"]}', NULL, 'co-investment arrangement / co-investment fund', '[{"en":"The bank offered a co-investment deal to corporate clients.","zh-TW":"銀行向企業客戶提供了共同投資方案。"},{"en":"Co-investment allows smaller investors to access larger deals.","zh-TW":"共同投資使較小的投資者能夠參與較大的交易。"}]', NULL, NULL, 5, 1185, NULL),
(1186, 'co-ownership', '/''kəʊˌəʊnərʃɪp/', 'noun', '{"zh-TW":["共同所有權；合有產權"],"en":["the joint ownership of property by two or more people"]}', NULL, 'enter into co-ownership / co-ownership arrangement / co-ownership agreement', '[{"en":"Co-ownership allows buyers to split the cost of purchasing a property.","zh-TW":"共同所有權允許買家分攤購買房產的費用。"},{"en":"The siblings entered into a co-ownership arrangement for the family home.","zh-TW":"兄弟姐妹就家庭住宅達成了共同所有權安排。"}]', NULL, NULL, 4, 1186, NULL),
(1187, 'co-payment', '/ˈkəʊˌpeɪmənt/', 'noun', '{"zh-TW":["共同負擔額；自負額"],"en":["the portion of a medical bill paid by the patient"]}', NULL, 'co-payment requirement / reduce co-payment', '[{"en":"The co-payment for a specialist visit is twenty dollars.","zh-TW":"專科門診的自負額是二十元。"},{"en":"Check your plan for the co-payment amount.","zh-TW":"請查看您的保險計劃的自負額金額。"}]', NULL, NULL, 4, 1187, NULL),
(1188, 'co-worker', '/ˈkəʊwɜːrkər/', 'noun', '{"zh-TW":["同事"],"en":["a person with whom one works"]}', NULL, 'get along with co-workers / support co-workers', '[{"en":"She gets along well with all her co-workers.","zh-TW":"她與所有同事相處融洽。"},{"en":"Co-workers supported each other during the busy season.","zh-TW":"在繁忙季節，同事們互相支持。"}]', NULL, NULL, 3, 1188, NULL),
(1189, 'coach', '/koʊtʃ/', 'noun', '{"zh-TW":["教練；長途巴士"],"en":["a person who trains sportspeople"]}', NULL, 'head coach / life coach', '[{"en":"The coach trained the team hard.","zh-TW":"教練嚴格訓練隊員。"},{"en":"She hired a life coach.","zh-TW":"她請了一位人生教練。"}]', '{"verb":"coach","noun2":"coaching"}', NULL, 2, 1189, NULL),
(1190, 'coaching', '/ˈkoʊtʃɪŋ/', 'noun', '{"zh-TW":["教練輔導；培訓"],"en":["a development process where a coach guides an individual to improve performance"]}', NULL, 'executive coaching / career coaching / coaching session', '[{"en":"The manager used coaching to help the struggling employee improve.","zh-TW":"主管使用教練輔導幫助掙扎中的員工改進。"},{"en":"Professional coaching can accelerate leadership development.","zh-TW":"專業教練輔導可以加速領導力發展。"}]', '{"verb":"coach","noun":"coach"}', NULL, 3, 1190, NULL),
(1191, 'coaching staff', '/''kəʊtʃɪŋ stɑːf/', 'noun', '{"zh-TW":["教練團隊；教練組"],"en":["the group of coaches and trainers responsible for preparing and directing an athletic team"]}', NULL, 'experienced coaching staff / coaching staff decision / assemble a coaching staff', '[{"en":"The team hired a new coaching staff with expertise in defensive tactics.","zh-TW":"球隊聘請了擅長防守戰術的新教練團隊。"},{"en":"The coaching staff analyzed video footage to identify areas for improvement.","zh-TW":"教練團隊分析了視頻片段以確定需要改進的地方。"}]', NULL, NULL, 5, 1191, NULL),
(1192, 'coast', '/koʊst/', 'noun', '{"zh-TW":["海岸"],"en":["the land next to the sea"]}', NULL, 'east coast / coast line', '[{"en":"We drove along the coast.","zh-TW":"我們沿著海岸開車。"},{"en":"The town is on the west coast.","zh-TW":"這個鎮在西海岸。"}]', '{"adjective":"coastal"}', NULL, 2, 1192, NULL),
(1193, 'coastal', '/ˈkoʊstl/', 'adjective', '{"zh-TW":["沿海的"],"en":["relating to or near the coast"]}', '{"root":{"text":"coast","meaning":"side/shore (海岸)"},"suffix":{"text":"-al","meaning":"relating to (相關的)"},"logic":"與海岸相關的。"}', 'coastal area / coastal city / coastal erosion', '[{"en":"Coastal cities are vulnerable to flooding.","zh-TW":"沿海城市容易受到洪水侵襲。"},{"en":"We drove along the coastal highway.","zh-TW":"我們沿著海岸公路開車。"}]', '{"noun":"coast"}', NULL, 3, 1193, NULL),
(1194, 'coastal path', '/''kəʊstəl pɑːθ/', 'noun', '{"zh-TW":["海岸步道；海濱小路"],"en":["a trail or path that runs along a coastline, offering views of the sea"]}', NULL, 'walk the coastal path / scenic coastal path / coastal path trail', '[{"en":"The coastal path from the village to the lighthouse took about two hours on foot.","zh-TW":"從村莊到燈塔的海岸步道步行約需兩小時。"},{"en":"She spent a week hiking the famous coastal path along the Cornish cliffs.","zh-TW":"她花了一週時間徒步沿著康沃爾懸崖上著名的海岸步道行走。"}]', NULL, NULL, 4, 1194, NULL),
(1195, 'coastal town', '/''kəʊstəl taʊn/', 'noun', '{"zh-TW":["海濱小鎮"],"en":["a small settlement located on or near the coast"]}', NULL, 'visit a coastal town / picturesque coastal town / quaint coastal town', '[{"en":"The picturesque coastal town attracted artists and photographers year-round.","zh-TW":"這個風景如畫的海濱小鎮全年吸引藝術家和攝影師。"},{"en":"We spent a relaxing weekend in a quiet coastal town far from the city.","zh-TW":"我們在遠離城市的寧靜海濱小鎮度過了一個輕鬆的週末。"}]', NULL, NULL, 4, 1195, NULL),
(1196, 'coat', '/koʊt/', 'noun', '{"zh-TW":["外套；塗層"],"en":["a piece of clothing worn over other clothes"]}', NULL, 'winter coat / coat of paint', '[{"en":"Put on your coat, it''s cold.","zh-TW":"穿上外套，外面很冷。"},{"en":"The wall needs another coat of paint.","zh-TW":"牆壁需要再塗一層漆。"}]', NULL, NULL, 1, 1196, NULL),
(1197, 'code', '/koʊd/', 'noun', '{"zh-TW":["密碼；代碼；法規"],"en":["a system of rules or symbols"]}', NULL, 'dress code / zip code', '[{"en":"What''s the door code?","zh-TW":"門的密碼是什麼？"},{"en":"There''s a strict dress code.","zh-TW":"有嚴格的著裝規定。"}]', '{"verb":"code"}', NULL, 1, 1197, NULL),
(1198, 'code of conduct', '/koʊd əv ˈkɒndʌkt/', 'noun', '{"zh-TW":["行為準則"],"en":["a set of rules governing the behavior of members of an organization"]}', NULL, 'comply with the code of conduct / violate the code of conduct', '[{"en":"All employees must sign and adhere to the code of conduct.","zh-TW":"所有員工必須簽署並遵守行為準則。"},{"en":"The code of conduct prohibits accepting gifts from suppliers.","zh-TW":"行為準則禁止接受供應商的禮品。"}]', NULL, NULL, 5, 1198, NULL),
(1199, 'code-switching', '/''kəʊd ˌswɪtʃɪŋ/', 'noun', '{"zh-TW":["語碼轉換；語言切換"],"en":["the practice of alternating between two or more languages or dialects in conversation"]}', NULL, 'engage in code-switching / code-switching in conversation / natural code-switching', '[{"en":"Code-switching is common in multilingual communities where several languages are spoken.","zh-TW":"在說幾種語言的多語言社區中，語碼轉換很常見。"},{"en":"She unconsciously engaged in code-switching when speaking with family members.","zh-TW":"她在與家人交談時無意識地進行了語碼轉換。"}]', '{"verb":"code-switch","adjective":"code-switched"}', NULL, 5, 1199, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(1200, 'codify', '/ˈkɒdɪfaɪ/', 'verb', '{"zh-TW":["編纂；使系統化"],"en":["to arrange laws or rules into a systematic code"]}', NULL, 'codify regulations / codify practices / codify standards', '[{"en":"The government codified environmental protections into law.","zh-TW":"政府將環境保護編纂成法律。"},{"en":"Best practices were codified into a formal handbook.","zh-TW":"最佳實踐被編纂成正式手冊。"}]', '{"noun":"codification","adjective":"codified"}', NULL, 2, 1200, NULL),
(1201, 'coefficient', '/ˌkəʊɪˈfɪʃənt/', 'noun', '{"zh-TW":["係數"],"en":["a numerical or constant quantity placed before a variable in an expression"]}', NULL, 'correlation coefficient / regression coefficient / coefficient of variation', '[{"en":"A high correlation coefficient indicates a strong relationship between variables.","zh-TW":"高相關係數表明變量之間存在強烈關係。"},{"en":"The Gini coefficient measures income inequality within a population.","zh-TW":"基尼係數測量人口內部的收入不平等。"}]', NULL, NULL, 4, 1201, NULL),
(1202, 'coercive', '/kəʊˈɜːrsɪv/', 'adjective', '{"zh-TW":["強制的；強迫的"],"en":["relating to the practice of persuading someone through force or threats"]}', NULL, 'coercive measures / coercive tactics / coercive behavior', '[{"en":"Coercive business practices that restrict competition are illegal.","zh-TW":"限制競爭的強制商業行為是非法的。"},{"en":"The court found evidence of coercive behavior in the employment contract.","zh-TW":"法院在僱傭合約中發現了強制行為的證據。"}]', '{"verb":"coerce","noun":"coercion","adverb":"coercively"}', NULL, 3, 1202, NULL),
(1203, 'coffee', '/ˈkɒfi/', 'noun', '{"zh-TW":["咖啡"],"en":["a hot drink made from roasted beans"]}', NULL, 'coffee shop / cup of coffee', '[{"en":"I need a cup of coffee.","zh-TW":"我需要一杯咖啡。"},{"en":"Let''s meet at the coffee shop.","zh-TW":"我們在咖啡店見面吧。"}]', NULL, NULL, 2, 1203, NULL),
(1204, 'cogent', '/''kəʊdʒənt/', 'adjective', '{"zh-TW":["有說服力的；切實的"],"en":["clear, logical, and convincing"]}', NULL, 'cogent argument / cogent analysis / cogent reasoning', '[{"en":"She presented a cogent argument that persuaded even the most skeptical board members.","zh-TW":"她提出了一個有說服力的論點，甚至說服了最懷疑的董事會成員。"},{"en":"A cogent analysis of the data supported the proposed policy change.","zh-TW":"對數據的切實分析支持了提議的政策變化。"}]', '{"adverb":"cogently","noun":"cogency"}', NULL, 2, 1204, NULL),
(1205, 'cognitive behavioral therapy', '/ˈkɒɡnɪtɪv bɪˈheɪvjərəl ˈθerəpi/', 'noun', '{"zh-TW":["認知行為療法"],"en":["a psychological treatment that modifies negative thoughts and behaviors"]}', NULL, 'undergo cognitive behavioral therapy / cognitive behavioral therapy session / evidence-based cognitive behavioral therapy', '[{"en":"Cognitive behavioral therapy is the most evidence-based treatment for depression.","zh-TW":"認知行為療法是治療抑鬱症最有實證支持的療法。"},{"en":"Cognitive behavioral therapy helps patients identify and change distorted thinking.","zh-TW":"認知行為療法幫助患者識別和改變扭曲的思維。"}]', NULL, NULL, 5, 1205, NULL),
(1206, 'cognitive bias', '/''kɒɡnɪtɪv ˌbaɪəs/', 'noun', '{"zh-TW":["認知偏誤；認知偏見"],"en":["a systematic error in thinking that affects judgment and decision-making"]}', NULL, 'identify cognitive bias / overcome cognitive bias / types of cognitive bias', '[{"en":"Confirmation bias is one of the most common cognitive biases in decision-making.","zh-TW":"確認偏誤是決策中最常見的認知偏誤之一。"},{"en":"Recognizing your own cognitive biases is the first step to making more rational choices.","zh-TW":"認識自己的認知偏誤是做出更理性選擇的第一步。"}]', '{"adjective":"cognitive"}', NULL, 5, 1206, NULL),
(1207, 'cognitive dissonance', '/ˈkɒɡnɪtɪv ˈdɪsənəns/', 'noun', '{"zh-TW":["認知失調"],"en":["the discomfort felt when holding conflicting beliefs or behaviors"]}', NULL, 'experience cognitive dissonance / cognitive dissonance theory / reduce cognitive dissonance', '[{"en":"Cognitive dissonance theory explains why people resist information that challenges their beliefs.","zh-TW":"認知失調理論解釋了為什麼人們抗拒挑戰其信念的資訊。"},{"en":"Voters experience cognitive dissonance when their candidate acts against their values.","zh-TW":"當選民的候選人的行為違背其價值觀時，他們會體驗到認知失調。"}]', NULL, NULL, 5, 1207, NULL),
(1208, 'cognitive load', '/ˈkɒɡnɪtɪv ləʊd/', 'noun', '{"zh-TW":["認知負擔"],"en":["the amount of mental effort required to process information"]}', NULL, 'reduce cognitive load / manage cognitive load / cognitive load theory', '[{"en":"Simplified instructions reduce cognitive load for new users.","zh-TW":"簡化的說明減少了新用戶的認知負擔。"},{"en":"Cognitive load theory guides instructional design in education.","zh-TW":"認知負荷理論指導教育中的教學設計。"}]', NULL, NULL, 5, 1208, NULL),
(1209, 'cognizant', '/ˈkɒɡnɪzənt/', 'adjective', '{"zh-TW":["意識到的；知道的"],"en":["having knowledge or being aware of"]}', NULL, 'cognizant of risks / remain cognizant / fully cognizant', '[{"en":"The board must be cognizant of all regulatory risks.","zh-TW":"董事會必須意識到所有監管風險。"},{"en":"She was fully cognizant of the implications of her decision.","zh-TW":"她完全意識到她決定的含意。"}]', NULL, NULL, 3, 1209, NULL),
(1210, 'coherence', '/kəʊˈhɪərəns/', 'noun', '{"zh-TW":["連貫性；一致性"],"en":["the quality of being logical and consistent"]}', NULL, 'logical coherence / narrative coherence / internal coherence', '[{"en":"The essay lacks coherence between its introduction and conclusion.","zh-TW":"這篇文章的引言和結論之間缺乏連貫性。"},{"en":"Policy coherence is essential for effective governance.","zh-TW":"政策連貫性對有效治理至關重要。"}]', '{"adjective":"coherent","adverb":"coherently"}', NULL, 3, 1210, NULL),
(1211, 'coherent', '/koʊˈhɪərənt/', 'adjective', '{"zh-TW":["連貫的；一致的"],"en":["logical and consistent; forming a united whole"]}', NULL, 'coherent strategy / coherent plan / coherent message', '[{"en":"The marketing team developed a coherent brand message.","zh-TW":"行銷團隊制定了連貫一致的品牌訊息。"},{"en":"A coherent strategy is essential for aligning team efforts.","zh-TW":"連貫的策略對於整合團隊努力至關重要。"}]', '{"adverb":"coherently","noun":"coherence"}', NULL, 3, 1211, 960),
(1212, 'coherent strategy', '/''kəʊˌhɪərənt ˌstrætədʒi/', 'noun', '{"zh-TW":["連貫的策略；一致的戰略"],"en":["a clear and logical plan of action that is internally consistent and aligns with overall objectives"]}', NULL, 'develop a coherent strategy / lack a coherent strategy / implement a coherent strategy', '[{"en":"Without a coherent strategy, the company''s marketing efforts were scattered and ineffective.","zh-TW":"沒有連貫的策略，公司的行銷工作分散且無效。"},{"en":"A coherent strategy gives employees direction and helps prioritize resources effectively.","zh-TW":"連貫的策略為員工提供方向，並幫助有效地優先考慮資源。"}]', NULL, NULL, 5, 1212, NULL),
(1213, 'coherently', '/''kəʊˈhɪərəntli/', 'adverb', '{"zh-TW":["連貫地；有條理地"],"en":["in a logical and consistent manner; in a way that is intelligible"]}', NULL, 'argue coherently / explain coherently / write coherently', '[{"en":"She was able to explain the complex concept coherently to a non-specialist audience.","zh-TW":"她能夠向非專業受眾連貫地解釋這個複雜概念。"},{"en":"The report was written coherently, with each section logically following the previous.","zh-TW":"報告連貫地撰寫，每個部分都符合邏輯地接續前一部分。"}]', '{"adjective":"coherent"}', NULL, 4, 1213, NULL),
(1214, 'cohesion', '/kəʊˈhiːʒən/', 'noun', '{"zh-TW":["凝聚力；結合"],"en":["the action or fact of forming a united whole"]}', NULL, 'team cohesion / social cohesion / textual cohesion', '[{"en":"Strong team cohesion improves collective performance.","zh-TW":"強大的團隊凝聚力能提升整體表現。"},{"en":"The essay demonstrates good cohesion between its paragraphs.","zh-TW":"這篇文章段落之間展現出良好的結合性。"}]', '{"adjective":"cohesive","adverb":"cohesively"}', NULL, 3, 1214, NULL),
(1215, 'cohesive', '/kəʊˈhiːsɪv/', 'adjective', '{"zh-TW":["有凝聚力的；黏合的"],"en":["characterized by unity and working together effectively"]}', NULL, 'cohesive team / cohesive strategy / socially cohesive', '[{"en":"A cohesive team performs better than a group of individuals working alone.","zh-TW":"一個有凝聚力的團隊比一群各自為戰的個人表現更好。"},{"en":"The brand needed a more cohesive visual identity across all platforms.","zh-TW":"品牌需要在所有平台上擁有更有凝聚力的視覺形象。"}]', '{"noun":"cohesion","adverb":"cohesively"}', NULL, 3, 1215, NULL),
(1216, 'coin', '/kɔɪn/', 'noun', '{"zh-TW":["硬幣"],"en":["a small piece of metal used as money"]}', NULL, 'flip a coin / coin a phrase', '[{"en":"I found a coin on the ground.","zh-TW":"我在地上發現了一枚硬幣。"},{"en":"Let''s flip a coin to decide.","zh-TW":"讓我們擲硬幣來決定。"}]', NULL, NULL, 1, 1216, NULL),
(1217, 'coincide', '/ˌkəʊɪnˈsaɪd/', 'verb', '{"zh-TW":["同時發生；巧合","巧合；同時發生"],"en":["to occur at the same time or place"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"incide","meaning":"fall upon (落入)"},"logic":"一起落入同一點，即「同時發生」。"}', 'coincide with / happen to coincide', '[{"en":"The product launch coincided with a major trade show.","zh-TW":"產品發布與一場大型貿易展同時舉行。"},{"en":"The meeting coincides with my vacation dates.","zh-TW":"會議與我的假期日期衝突。"},{"en":"My vacation coincides with the conference.","zh-TW":"我的假期和會議撞期。"},{"en":"The two events coincided by chance.","zh-TW":"兩件事巧合地同時發生。"}]', '{"noun":"coincidence","adjective":"coincidental"}', NULL, 3, 1217, NULL),
(1218, 'coinsurance', '/ˌkoʊɪnˈʃʊərəns/', 'noun', '{"zh-TW":["共同保險；自付比例"],"en":["shared insurance where the insured pays a portion of a loss beyond the deductible"]}', NULL, 'coinsurance clause / coinsurance percentage', '[{"en":"The policy has a 20% coinsurance requirement after the deductible.","zh-TW":"保單在免賠額後有20%的共同保險要求。"},{"en":"Coinsurance encourages policyholders to insure properties at full value.","zh-TW":"共同保險鼓勵保單持有人按全值對財產投保。"}]', NULL, NULL, 4, 1218, NULL),
(1219, 'cold', '/koʊld/', 'adjective', '{"zh-TW":["冷的；冷淡的","冷的；感冒"],"en":["having a low temperature","unfriendly"]}', NULL, 'cold call / cold storage; catch a cold / cold weather', '[{"en":"Cold calling is part of sales training.","zh-TW":"電話開發是銷售訓練的一部分。"},{"en":"Keep the samples in cold storage.","zh-TW":"將樣品放在冷藏庫中。"},{"en":"It''s very cold outside.","zh-TW":"外面很冷。"},{"en":"She caught a cold last week.","zh-TW":"她上星期感冒了。"}]', '{"adjective":"cold","noun":"cold","adverb":"coldly"}', NULL, 1, 1219, NULL),
(1220, 'cold call', '/kəʊld kɔːl/', 'noun', '{"zh-TW":["陌生電話拜訪；冷電話"],"en":["a sales call made to someone with no prior relationship"]}', NULL, 'make a cold call / cold call script', '[{"en":"The salesperson made fifty cold calls every day.","zh-TW":"銷售員每天撥打五十個陌生電話。"},{"en":"Cold calling is a traditional but challenging sales technique.","zh-TW":"陌生電話拜訪是一種傳統但具有挑戰性的銷售技術。"}]', '{"verb":"cold call"}', NULL, 3, 1220, NULL),
(1221, 'cold calling', '/koʊld ˈkɔːlɪŋ/', 'noun', '{"zh-TW":["陌生電話拜訪；冷電話"],"en":["contacting potential customers who have had no prior interaction with the company"]}', NULL, 'cold calling script / cold calling campaign / effective cold calling', '[{"en":"Cold calling remains a core tactic for B2B sales teams.","zh-TW":"冷電話仍然是B2B銷售團隊的核心策略。"},{"en":"He made 50 cold calls a day during the initial sales push.","zh-TW":"在最初的銷售衝刺期間，他每天打50個冷電話。"}]', '{"verb":"cold call"}', NULL, 4, 1221, NULL),
(1222, 'cold chain', '/''kəʊld tʃeɪn/', 'noun', '{"zh-TW":["冷鏈物流"],"en":["a temperature-controlled supply chain used to maintain the quality of perishable goods"]}', NULL, 'maintain the cold chain / cold chain logistics / cold chain disruption', '[{"en":"Vaccines and fresh food require cold chain logistics to remain effective and safe.","zh-TW":"疫苗和新鮮食物需要冷鏈物流才能保持有效性和安全性。"},{"en":"Breaking the cold chain can cause food spoilage and safety issues.","zh-TW":"打斷冷鏈可能導致食品腐敗和安全問題。"}]', NULL, NULL, 4, 1222, NULL),
(1223, 'cold chain logistics', '/''kəʊld tʃeɪn ləˌdʒɪstɪks/', 'noun', '{"zh-TW":["冷鏈物流"],"en":["the management and transportation of temperature-sensitive products through a controlled temperature supply chain"]}', NULL, 'maintain cold chain logistics / cold chain logistics system / benefit of cold chain logistics', '[{"en":"Pharmaceuticals and perishable foods require carefully managed cold chain logistics.","zh-TW":"藥品和易腐壞食品需要精心管理的冷鏈物流。"},{"en":"Any break in cold chain logistics can compromise the safety and quality of the product.","zh-TW":"冷鏈物流的任何中斷都可能損害產品的安全性和質量。"}]', '{"noun":"cold chain"}', NULL, 5, 1223, NULL),
(1224, 'cold email', '/''kəʊld ˌiːmeɪl/', 'noun', '{"zh-TW":["冷郵件；陌生開發郵件"],"en":["an unsolicited email sent to someone you have not previously contacted in an attempt to establish a business relationship"]}', NULL, 'send a cold email / write a cold email / effective cold email', '[{"en":"She sent a cold email to the CEO of a startup she admired and secured an interview.","zh-TW":"她向她欣賞的一家新創公司的首席執行官發了一封冷郵件，獲得了面試機會。"},{"en":"A well-crafted cold email should be concise, personalized, and offer clear value.","zh-TW":"一封精心製作的冷郵件應該簡潔、個性化，並提供明確的價值。"}]', NULL, NULL, 4, 1224, NULL),
(1225, 'collaborate', '/kəˈlæbəreɪt/', 'verb', '{"zh-TW":["合作；協作"],"en":["to work jointly on an activity or project"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"labor","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'collaborate with / collaborate on a project', '[{"en":"The two companies collaborated on the research project.","zh-TW":"兩家公司在研究專案上合作。"},{"en":"Teams must collaborate effectively to meet deadlines.","zh-TW":"團隊必須有效合作以趕上截止日期。"}]', '{"noun":"collaboration","adjective":"collaborative"}', NULL, 4, 1225, 290),
(1226, 'collaboration', '/kəˌlæbəˈreɪʃən/', 'noun', '{"zh-TW":["合作；協作"],"en":["working jointly with others toward a common goal"]}', NULL, 'cross-team collaboration / collaboration tools / foster collaboration', '[{"en":"Collaboration between departments led to an innovative solution.","zh-TW":"各部門之間的合作帶來了創新的解決方案。"},{"en":"Remote tools have improved collaboration across time zones.","zh-TW":"遠端工具改善了跨時區的協作。"}]', '{"verb":"collaborate","adjective":"collaborative"}', NULL, 5, 1226, 523),
(1227, 'collaborative', 'kəˈlæbərətɪv', 'adjective', '{"zh-TW":["協作的；合作的","共同參與的"],"en":["involving joint effort","working together"]}', NULL, 'collaborative approach/collaborative team', '[{"en":"We encourage a collaborative work culture.","zh-TW":"我們鼓勵協作的工作文化。"}]', '{"noun":"collaboration","adverb":"collaboratively"}', NULL, 5, 1227, NULL),
(1228, 'collage', '/kɒˈlɑːʒ/', 'noun', '{"zh-TW":["拼貼藝術"],"en":["an art form in which various materials are arranged and glued together"]}', NULL, 'create a collage / photo collage / artistic collage', '[{"en":"The artist created a striking collage from newspaper clippings and photographs.","zh-TW":"藝術家用報紙剪報和照片製作了一幅引人注目的拼貼畫。"},{"en":"Collage became a defining technique of the Dada movement.","zh-TW":"拼貼成為達達主義運動的決定性技術。"}]', '{"verb":"collage"}', NULL, 3, 1228, NULL),
(1229, 'collapse', '/kəˈlæps/', 'verb', '{"zh-TW":["崩潰；倒塌","崩塌；倒下"],"en":["to fall down or give way suddenly","to fail suddenly and completely","to fall down suddenly","to fail completely"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lapse","meaning":"fall (落下)"},"logic":"一起落下，即「崩潰」。"}', 'collapse of / market collapse / building collapse; collapse under pressure / building collapse', '[{"en":"The housing market collapsed during the financial crisis.","zh-TW":"房地產市場在金融危機期間崩盤。"},{"en":"Negotiations collapsed over pricing disagreements.","zh-TW":"談判因價格分歧而破裂。"},{"en":"The bridge collapsed during the earthquake.","zh-TW":"橋樑在地震中倒塌。"},{"en":"The company collapsed due to poor management.","zh-TW":"公司因管理不善而倒閉。"}]', '{"noun":"collapse"}', NULL, 3, 1229, NULL),
(1230, 'collate', '/kəˈleɪt/', 'verb', '{"zh-TW":["整理；匯編"],"en":["to gather and organize material in a proper order"]}', NULL, 'collate data / collate feedback / collate reports', '[{"en":"She collated all the survey responses into a single spreadsheet.","zh-TW":"她將所有調查回覆整理到一個電子表格中。"},{"en":"The analyst collated data from five different sources.","zh-TW":"分析師從五個不同來源匯編了資料。"}]', '{"noun":"collation","adjective":"collated"}', NULL, 3, 1230, NULL),
(1231, 'collateral', '/kəˈlætərəl/', 'noun', '{"zh-TW":["擔保品；抵押品"],"en":["an asset pledged as security for a loan"]}', NULL, 'post collateral / collateral requirement / loan collateral', '[{"en":"The bank required collateral before approving the loan.","zh-TW":"銀行在批准貸款前要求提供抵押品。"},{"en":"Property is commonly used as collateral for mortgages.","zh-TW":"財產通常用作抵押貸款的抵押品。"}]', '{"adjective":"collateral"}', NULL, 4, 1231, 839),
(1232, 'collateral agreement', '/kəˈlætərəl əˈɡriːmənt/', 'noun', '{"zh-TW":["附屬協議；附帶協議"],"en":["an agreement supplementary to a main contract addressing specific side terms"]}', NULL, 'enter a collateral agreement / collateral agreement terms', '[{"en":"A collateral agreement was signed to address the warranty terms separately.","zh-TW":"簽訂了附屬協議以單獨處理保固條款。"},{"en":"Collateral agreements must not contradict the main contract''s provisions.","zh-TW":"附屬協議不得與主合約的條款相抵觸。"}]', NULL, NULL, 5, 1232, NULL),
(1233, 'collateral damage', '/kəˈlætərəl ˈdæmɪdʒ/', 'noun', '{"zh-TW":["附帶損害；意外損失"],"en":["unintended harm caused by an action targeting something else"]}', NULL, 'avoid collateral damage / minimize collateral damage', '[{"en":"The restructuring caused collateral damage to team morale.","zh-TW":"重組對團隊士氣造成了附帶損害。"},{"en":"Budget cuts resulted in collateral damage to key service quality.","zh-TW":"預算削減導致了關鍵服務品質的意外損失。"}]', NULL, NULL, 5, 1233, NULL),
(1234, 'collateralize', '/kəˈlætərəlaɪz/', 'verb', '{"zh-TW":["提供抵押品；以…作擔保"],"en":["to pledge an asset as collateral for a loan"]}', NULL, 'collateralize a loan / collateralize assets / fully collateralized', '[{"en":"The bank required the borrower to collateralize the debt.","zh-TW":"銀行要求借款人為債務提供抵押品。"},{"en":"Mortgage-backed securities are collateralized by home loans.","zh-TW":"抵押支持證券以住房貸款作擔保。"}]', '{"noun":"collateralization","adjective":"collateralized"}', NULL, 5, 1234, NULL),
(1235, 'collateralized debt obligation', '/kəˈlætərəlaɪzd det ˌɒblɪˈɡeɪʃən/', 'noun', '{"zh-TW":["擔保債務憑證"],"en":["a structured finance product backed by a pool of loans or bonds"]}', NULL, 'create a collateralized debt obligation / invest in collateralized debt obligations / collateralized debt obligation market', '[{"en":"Collateralized debt obligations repackage pools of loans into new securities with different risk levels.","zh-TW":"擔保債務憑證將貸款池重新包裝成具有不同風險級別的新證券。"},{"en":"The collapse of collateralized debt obligation markets played a key role in the 2008 financial crisis.","zh-TW":"擔保債務憑證市場的崩潰在二○○八年金融危機中扮演了關鍵角色。"}]', NULL, NULL, 5, 1235, NULL),
(1236, 'colleague', '/ˈkɒliːɡ/', 'noun', '{"zh-TW":["同事"],"en":["a person with whom one works in a profession"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"league","meaning":"choose/gather (選擇/聚集)"},"logic":"一起被選擇聚集的人，即「同事」。"}', 'work colleague / former colleague', '[{"en":"I discussed the proposal with my colleagues.","zh-TW":"我與同事討論了該提案。"},{"en":"She is well respected by her colleagues.","zh-TW":"她深受同事尊敬。"}]', NULL, NULL, 3, 1236, 81),
(1237, 'collect', '/kəˈlekt/', 'verb', '{"zh-TW":["收集；收取"],"en":["to bring or gather together","to call for and receive payment"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lect","meaning":"gather (聚集)"},"logic":"聚集在一起，即「收集」。"}', 'collect data/feedback/payment', '[{"en":"We collect customer feedback through surveys.","zh-TW":"我們透過調查收集客戶反饋。"},{"en":"The agency collects rent on behalf of landlords.","zh-TW":"代理機構代房東收取租金。"}]', '{"noun":"collection"}', NULL, 3, 1237, 291),
(1238, 'collective action', '/kəˈlektɪv ˈækʃən/', 'noun', '{"zh-TW":["集體行動"],"en":["concerted action taken by a group to achieve a shared goal"]}', NULL, 'coordinate collective action / collective action problem', '[{"en":"Collective action by suppliers led to better payment terms.","zh-TW":"供應商的集體行動帶來了更好的付款條款。"},{"en":"Solving climate change requires collective action across industries.","zh-TW":"解決氣候變化需要跨行業的集體行動。"}]', NULL, NULL, 5, 1238, NULL),
(1239, 'collective agreement', '/kəˈlɛktɪv əˈɡriːmənt/', 'noun', '{"zh-TW":["集體協議；勞資集體合約"],"en":["a negotiated agreement between an employer and a union"]}', NULL, 'negotiate a collective agreement / collective agreement terms', '[{"en":"The union reached a collective agreement with management.","zh-TW":"工會與管理層達成了集體協議。"},{"en":"Wage increases were specified in the collective agreement.","zh-TW":"集體協議中規定了薪資增加幅度。"}]', NULL, NULL, 5, 1239, NULL),
(1240, 'collective bargaining', '/kəˈlektɪv ˈbɑːrɡɪnɪŋ/', 'noun', '{"zh-TW":["集體談判"],"en":["negotiation between employers and a group of employees or their union"]}', NULL, 'collective bargaining agreement / collective bargaining process', '[{"en":"Collective bargaining resulted in higher wages for factory workers.","zh-TW":"集體談判為工廠工人爭取到了更高的工資。"},{"en":"The union entered collective bargaining to improve working conditions.","zh-TW":"工會進行集體談判以改善工作條件。"}]', '{"verb":"bargain collectively"}', NULL, 5, 1240, NULL),
(1241, 'college', '/ˈkɒlɪdʒ/', 'noun', '{"zh-TW":["大學；學院"],"en":["an institution for higher education"]}', NULL, 'go to college / college degree', '[{"en":"She went to college in Boston.","zh-TW":"她在波士頓上大學。"},{"en":"A college degree opens many doors.","zh-TW":"大學學位能開啟很多機會。"}]', NULL, NULL, 3, 1241, NULL),
(1242, 'colloquial', '/''kəˈləʊkwiəl/', 'adjective', '{"zh-TW":["口語的；口頭的；非正式的"],"en":["used in ordinary or familiar conversation; informal"]}', NULL, 'colloquial language / colloquial expression / colloquial speech', '[{"en":"She avoided colloquial language in her formal business presentation.","zh-TW":"她在正式商業演示中避免使用口語語言。"},{"en":"Learning colloquial expressions can help you sound more natural in everyday conversation.","zh-TW":"學習口語表達有助於你在日常對話中聽起來更自然。"}]', '{"noun":"colloquialism","adverb":"colloquially"}', NULL, 4, 1242, NULL),
(1243, 'color', '/ˈkʌlər/', 'noun', '{"zh-TW":["顏色"],"en":["the appearance of things resulting from light"]}', NULL, 'favorite color / color blind', '[{"en":"What''s your favorite color?","zh-TW":"你最喜歡什麼顏色？"},{"en":"The leaves change color in fall.","zh-TW":"秋天葉子會變色。"}]', '{"adjective":"colorful","verb":"color"}', NULL, 2, 1243, NULL),
(1244, 'column', '/ˈkɒləm/', 'noun', '{"zh-TW":["欄；柱"],"en":["a vertical division of a page","a pillar supporting a structure"]}', '{"root":{"text":"column","meaning":"pillar (柱子)"},"logic":"源自拉丁語 columna（柱子），引申為報紙或表格的直行。"}', 'newspaper column / column chart / support column', '[{"en":"The data is organized in three columns.","zh-TW":"數據以三欄組織排列。"},{"en":"She writes a weekly column for the newspaper.","zh-TW":"她為報紙寫每週專欄。"}]', '{"noun":"columnist"}', NULL, 2, 1244, NULL),
(1245, 'column chart', '/ˈkɒləm tʃɑːrt/', 'noun', '{"zh-TW":["柱狀圖"],"en":["a chart using vertical bars to compare data"]}', NULL, 'create a column chart / column chart analysis', '[{"en":"The column chart showed sales growth over five years.","zh-TW":"柱狀圖顯示了五年來的銷售增長情況。"},{"en":"Use a column chart to compare data across categories.","zh-TW":"使用柱狀圖比較不同類別的數據。"}]', NULL, NULL, 4, 1245, NULL),
(1246, 'combination', '/ˌkɒmbɪˈneɪʃn/', 'noun', '{"zh-TW":["組合；結合"],"en":["a joining of different things"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"bin","meaning":"two (二)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"把兩個以上的東西放在一起的過程，即「組合」。"}', 'a combination of / winning combination', '[{"en":"The dish uses a combination of herbs and spices.","zh-TW":"這道菜使用了多種香草和香料的組合。"},{"en":"Success requires a combination of talent and hard work.","zh-TW":"成功需要天賦和努力的結合。"}]', '{"verb":"combine"}', NULL, 4, 1246, 292),
(1247, 'come', '/kʌm/', 'verb', '{"zh-TW":["來；到來"],"en":["to move toward","to arrive"]}', NULL, 'come up with / come across', '[{"en":"She came up with a brilliant idea.","zh-TW":"她想出了一個絕妙的點子。"},{"en":"Please come to my office at noon.","zh-TW":"請中午到我的辦公室來。"}]', '{"verb":"come","noun":"outcome","adjective":"incoming"}', NULL, 1, 1247, NULL),
(1248, 'comedy', '/ˈkɒmədi/', 'noun', '{"zh-TW":["喜劇"],"en":["entertainment that makes people laugh"]}', NULL, 'romantic comedy / comedy show', '[{"en":"I prefer comedies to horror films.","zh-TW":"比起恐怖片我更喜歡喜劇。"},{"en":"The comedy show was hilarious.","zh-TW":"那場喜劇表演太好笑了。"}]', '{"noun2":"comedian"}', NULL, 2, 1248, NULL),
(1249, 'comfort', '/ˈkʌmfərt/', 'noun', '{"zh-TW":["舒適；安慰"],"en":["a state of ease; something that gives relief","a state of physical ease","something that gives consolation"]}', '{"prefix":{"text":"com-","meaning":"with (一起)"},"root":{"text":"fort","meaning":"strong (強)"},"logic":"使人感到堅強安心，即「安慰」。"}', 'comfort zone / cold comfort; creature comfort / comfort zone / take comfort', '[{"en":"The hotel offers great comfort.","zh-TW":"這家飯店提供極佳的舒適度。"},{"en":"Step out of your comfort zone.","zh-TW":"走出你的舒適圈。"},{"en":"The hotel offers every comfort.","zh-TW":"飯店提供一切舒適設施。"},{"en":"She took comfort in her friend''s words.","zh-TW":"她從朋友的話語中得到安慰。"}]', '{"adjective":"comfortable","verb":"comfort","adverb":"comfortably"}', NULL, 3, 1249, NULL);
