(1250, 'comfortable', 'ˈkʌmftəbəl', 'adjective', '{"zh-TW":["舒適的；自在的","輕鬆的"],"en":["physically relaxed","at ease"]}', NULL, 'comfortable environment/comfortable with', '[{"en":"Are you comfortable with the new system?","zh-TW":"您對新系統感到習慣嗎？"}]', '{"noun":"comfort","adverb":"comfortably"}', NULL, 4, 1250, NULL),
(1251, 'command', '/kəˈmænd/', 'noun', '{"zh-TW":["命令；指揮"],"en":["an order given","control or authority over something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mand","meaning":"order (命令)"},"logic":"向大家發出命令，即「指揮」。"}', 'give a command / chain of command / command of', '[{"en":"The officer gave the command to advance.","zh-TW":"軍官下達了前進的命令。"},{"en":"She has a good command of English.","zh-TW":"她的英語掌握得很好。"}]', '{"verb":"command","noun2":"commander"}', NULL, 3, 1251, NULL),
(1252, 'commence', '/kəˈmens/', 'verb', '{"zh-TW":["開始；著手"],"en":["to begin or start something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mence","meaning":"begin (開始)"},"logic":"一起開始，即「開始」。"}', 'commence operations/work/proceedings', '[{"en":"Construction will commence in early March.","zh-TW":"工程將於三月初開始。"},{"en":"The meeting commenced at 9 AM sharp.","zh-TW":"會議在上午9點整開始。"}]', '{"noun":"commencement"}', NULL, 3, 1252, 654),
(1253, 'commencement', '/kəˈmɛnsmənt/', 'noun', '{"zh-TW":["開學；畢業典禮"],"en":["a ceremony at which degrees are conferred"]}', NULL, 'commencement ceremony / commencement speech', '[{"en":"The commencement ceremony will be held outdoors this year.","zh-TW":"今年的畢業典禮將在戶外舉行。"},{"en":"She delivered the commencement speech as valedictorian.","zh-TW":"她以第一名的身份發表了畢業演講。"}]', '{"verb":"commence"}', NULL, 4, 1253, 992),
(1254, 'commendable', '/''kəˌmendəbəl/', 'adjective', '{"zh-TW":["值得稱讚的；可嘉的"],"en":["deserving praise; praiseworthy"]}', NULL, 'commendable effort / commendable performance / commendable attitude', '[{"en":"Her commendable attitude toward client service earned her an employee of the month award.","zh-TW":"她對客戶服務的可嘉態度為她贏得了月度最佳員工獎。"},{"en":"The team''s commendable performance under pressure impressed the entire organization.","zh-TW":"團隊在壓力下的值得稱讚的表現令整個組織印象深刻。"}]', '{"adverb":"commendably","verb":"commend","noun":"commendation"}', NULL, 4, 1254, NULL),
(1255, 'commensurate', '/kəˈmenʃərɪt/', 'adjective', '{"zh-TW":["相稱的；成比例的"],"en":["corresponding in size or degree; proportionate"]}', NULL, 'commensurate with experience / commensurate salary / commensurate increase', '[{"en":"Compensation should be commensurate with the responsibilities of the role.","zh-TW":"薪酬應與職責相稱。"},{"en":"The penalty was commensurate with the severity of the regulatory violation.","zh-TW":"處罰與監管違規的嚴重程度相稱。"}]', '{"adverb":"commensurately"}', NULL, 4, 1255, NULL),
(1256, 'comment', '/ˈkɒment/', 'noun', '{"zh-TW":["評論；意見"],"en":["a verbal or written remark expressing an opinion"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ment","meaning":"mind (心智)"},"logic":"完全出自心智的話，即「評論」。"}', 'make a comment / no comment / comment on', '[{"en":"The manager declined to comment on the rumors.","zh-TW":"經理拒絕對傳聞發表評論。"},{"en":"We welcome comments from our customers.","zh-TW":"我們歡迎客戶的意見。"}]', '{"noun":"commentary"}', NULL, 3, 1256, NULL),
(1257, 'commerce', '/ˈkɒmɜːrs/', 'noun', '{"zh-TW":["商業；貿易"],"en":["the activity of buying and selling on a large scale"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"merce","meaning":"trade (交易)"},"logic":"一起交易，即「商業」。"}', 'e-commerce / chamber of commerce / international commerce', '[{"en":"E-commerce has transformed the retail industry.","zh-TW":"電子商務已改變了零售產業。"},{"en":"International commerce drives economic growth.","zh-TW":"國際貿易推動經濟成長。"}]', '{"adjective":"commercial","verb":"commercialize"}', NULL, 3, 1257, NULL),
(1258, 'commercial agreement', '/kəˈmɜːrʃəl əˈɡriːmənt/', 'noun', '{"zh-TW":["商業協議"],"en":["a legally binding contract between businesses for a commercial purpose"]}', NULL, 'sign a commercial agreement / commercial agreement terms', '[{"en":"The commercial agreement covered pricing, delivery, and warranty terms.","zh-TW":"商業協議涵蓋了定價、交貨和保修條款。"},{"en":"A commercial agreement was signed to formalize the distribution arrangement.","zh-TW":"簽署了商業協議以正式確認分銷安排。"}]', NULL, NULL, 5, 1258, NULL),
(1259, 'commercial invoice', '/kəˈmɜːrʃəl ˈɪnvɔɪs/', 'noun', '{"zh-TW":["商業發票"],"en":["an invoice used in international trade for customs purposes"]}', NULL, 'prepare a commercial invoice / commercial invoice requirements', '[{"en":"A commercial invoice is required for all international shipments.","zh-TW":"所有國際貨運都需要商業發票。"},{"en":"The commercial invoice must describe the goods and their value.","zh-TW":"商業發票必須描述貨物及其價值。"}]', NULL, NULL, 5, 1259, NULL),
(1260, 'commercial law', '/kəˈmɜːrʃəl lɔː/', 'noun', '{"zh-TW":["商法；商業法"],"en":["the body of law governing business and trade"]}', NULL, 'practice commercial law / commercial law expertise', '[{"en":"Commercial law governs contracts, employment, and company matters.","zh-TW":"商法規範合約、就業和公司事務。"},{"en":"The company retained a specialist in commercial law for the acquisition.","zh-TW":"公司聘請了商法專家負責收購事宜。"}]', NULL, NULL, 5, 1260, NULL),
(1261, 'commercial lease', '/kəˈmɜːrʃəl liːs/', 'noun', '{"zh-TW":["商業租賃"],"en":["a lease agreement for business premises between a landlord and a commercial tenant"]}', NULL, 'sign a commercial lease / commercial lease terms', '[{"en":"The startup signed a commercial lease for 500 square meters of office space.","zh-TW":"初創公司為500平方米的辦公空間簽署了商業租賃合約。"},{"en":"Commercial lease terms typically include rent review and break clauses.","zh-TW":"商業租賃條款通常包括租金審查和提前終止條款。"}]', NULL, NULL, 5, 1261, NULL),
(1262, 'commercial paper', '/kəˈmɜːrʃəl ˈpeɪpər/', 'noun', '{"zh-TW":["商業本票；商業票據"],"en":["short-term unsecured promissory notes issued by corporations"]}', NULL, 'issue commercial paper / commercial paper market', '[{"en":"The company raised funds through commercial paper to cover working capital.","zh-TW":"公司通過商業本票籌集資金以涵蓋營運資金。"},{"en":"Commercial paper is a cost-effective short-term financing tool.","zh-TW":"商業本票是一種具有成本效益的短期融資工具。"}]', NULL, NULL, 5, 1262, NULL),
(1263, 'commercial property', '/kəˈmɜːrʃəl ˈprɒpəti/', 'noun', '{"zh-TW":["商業地產"],"en":["real estate used for business purposes, such as offices, retail, or warehouses"]}', NULL, 'invest in commercial property / commercial property market / lease commercial property', '[{"en":"The company acquired commercial property in the city center.","zh-TW":"公司收購了市中心的商業地產。"},{"en":"Commercial property values fell during the economic downturn.","zh-TW":"經濟低迷期間商業地產價值下降。"}]', '{"plural":"commercial properties"}', NULL, 5, 1263, NULL),
(1264, 'commission', '/kəˈmɪʃn/', 'noun', '{"zh-TW":["佣金；委員會"],"en":["a payment to an agent","a group appointed for a duty"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"一起被派出的，即「委員會；佣金」。"}', 'sales commission / earn commission / commission a study', '[{"en":"Sales staff earn a 5% commission on each deal.","zh-TW":"銷售人員每筆交易可獲得5%佣金。"},{"en":"The commission will investigate the matter.","zh-TW":"委員會將調查此事。"}]', NULL, NULL, 4, 1264, 83),
(1265, 'commission rate', '/kəˈmɪʃən reɪt/', 'noun', '{"zh-TW":["佣金率"],"en":["the percentage of a sale paid as commission to a salesperson"]}', NULL, 'negotiate commission rate / set commission rate', '[{"en":"The sales rep earns a 5% commission rate on all direct sales.","zh-TW":"銷售代表從所有直接銷售中賺取5%的佣金率。"},{"en":"The company raised the commission rate to attract top salespeople.","zh-TW":"公司提高了佣金率以吸引頂尖銷售人員。"}]', NULL, NULL, 5, 1265, NULL),
(1266, 'commission structure', '/kəˈmɪʃən ˈstrʌktʃər/', 'noun', '{"zh-TW":["佣金結構"],"en":["the system determining how sales commissions are calculated and paid"]}', NULL, 'design a commission structure / commission structure policy', '[{"en":"The new commission structure rewards top performers with higher rates.","zh-TW":"新的佣金結構以更高的費率獎勵頂尖表現者。"},{"en":"A transparent commission structure motivates the sales team.","zh-TW":"透明的佣金結構激勵了銷售團隊。"}]', NULL, NULL, 5, 1266, NULL),
(1267, 'commit', '/kəˈmɪt/', 'verb', '{"zh-TW":["承諾；投入","犯（罪）","承諾；犯(罪)"],"en":["to pledge or dedicate oneself to","to carry out something illegal","to pledge or dedicate","to carry out a crime"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"完全送出自己，即「承諾」。"}', 'commit to / commit resources / commit a crime; commit to / commit a crime / fully committed', '[{"en":"The company committed $1 million to the initiative.","zh-TW":"公司投入100萬美元於該計畫。"},{"en":"We are committed to delivering quality service.","zh-TW":"我們致力於提供優質服務。"},{"en":"She committed herself to finishing the project.","zh-TW":"她承諾完成這個專案。"},{"en":"He committed a serious offense.","zh-TW":"他犯了一項嚴重罪行。"}]', '{"noun":"commitment","adjective":"committed"}', NULL, 2, 1267, 730),
(1268, 'commitment', '/kəˈmɪtmənt/', 'noun', '{"zh-TW":["承諾；投入"],"en":["a pledge or undertaking","dedication to a cause"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ment","meaning":"state (狀態)"},"logic":"完全送出自己的狀態，即「承諾」。"}', 'make a commitment / strong commitment / commitment to quality', '[{"en":"Our commitment to quality is unwavering.","zh-TW":"我們對品質的承諾堅定不移。"},{"en":"The project requires a significant time commitment.","zh-TW":"該專案需要投入大量時間。"}]', '{"verb":"commit","adjective":"committed"}', NULL, 4, 1268, 84),
(1269, 'commitment to quality', '/kəˈmɪtmənt tə ˈkwɒlɪti/', 'noun', '{"zh-TW":["品質承諾；品質決心"],"en":["a dedication to maintaining or exceeding defined quality standards"]}', NULL, 'demonstrate commitment to quality / commitment to quality standards', '[{"en":"The manufacturer''s commitment to quality earned it multiple certifications.","zh-TW":"製造商的品質承諾為其贏得了多項認證。"},{"en":"A commitment to quality is central to the company brand promise.","zh-TW":"品質承諾是公司品牌承諾的核心。"}]', NULL, NULL, 5, 1269, NULL),
(1270, 'committed facility', '/kəˈmɪtɪd fəˈsɪlɪti/', 'noun', '{"zh-TW":["承諾融資額度"],"en":["a formal agreement by a bank to provide funds up to an agreed limit on demand"]}', NULL, 'secure a committed facility / committed facility terms', '[{"en":"The company secured a $50 million committed facility from its lending syndicate.","zh-TW":"公司從其貸款銀團獲得了5000萬元的承諾融資額度。"},{"en":"A committed facility provides certainty of funding for strategic investments.","zh-TW":"承諾融資額度為戰略投資提供了資金確定性。"}]', '{"opposite":"uncommitted facility"}', NULL, 5, 1270, NULL),
(1271, 'committee', '/kəˈmɪti/', 'noun', '{"zh-TW":["委員會"],"en":["a group of people appointed for a specific function"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ee","meaning":"those who (…的人們)"},"logic":"一起被派出處理事務的人，即「委員會」。"}', 'steering committee / advisory committee / committee meeting', '[{"en":"The committee meets monthly to review progress.","zh-TW":"委員會每月開會檢視進度。"},{"en":"A new committee was formed to address the issue.","zh-TW":"成立了新委員會來處理此議題。"}]', NULL, NULL, 3, 1271, NULL),
(1272, 'commodification', '/kəˌmɒdɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["商品化"],"en":["the process of turning something into an object of commercial trade"]}', NULL, 'commodification of culture / commodification of data / commodification of education', '[{"en":"The commodification of personal data raises serious privacy concerns.","zh-TW":"個人數據的商品化引發了嚴重的隱私問題。"},{"en":"Critics argue that the commodification of education reduces its social value.","zh-TW":"批評者認為，教育的商品化降低了其社會價值。"}]', '{"verb":"commodify","adjective":"commodified"}', NULL, 5, 1272, NULL),
(1273, 'commodify', '/kəˈmɒdɪfaɪ/', 'verb', '{"zh-TW":["商品化；將…商業化"],"en":["to treat something as a commodity; to assign commercial value to something"]}', NULL, 'commodify data / commodify culture / commodify knowledge', '[{"en":"Critics argue that the gig economy commodifies labor in harmful ways.","zh-TW":"批評者認為，零工經濟以有害的方式將勞動力商品化。"},{"en":"The internet has commodified information that was previously difficult to access.","zh-TW":"互聯網將以前難以獲取的信息商品化了。"}]', '{"noun":"commodification","adjective":"commodified"}', NULL, 3, 1273, NULL),
(1274, 'commodities', '/kəˈmɒdɪtiz/', 'noun', '{"zh-TW":["大宗商品；原物料"],"en":["basic goods such as metals, energy, and agricultural products traded in bulk"]}', NULL, 'commodity prices / trade commodities / commodity market', '[{"en":"Rising commodity prices pushed up manufacturing costs.","zh-TW":"大宗商品價格上漲推高了製造成本。"},{"en":"Oil and copper are among the most widely traded commodities.","zh-TW":"石油和銅是交易最廣泛的大宗商品之一。"}]', '{"singular":"commodity","adjective":"commodity"}', NULL, 4, 1274, NULL),
(1275, 'commodities market', '/kəˈmɒdɪtɪz ˈmɑːrkɪt/', 'noun', '{"zh-TW":["大宗商品市場"],"en":["a market where raw materials and primary goods are bought and sold"]}', NULL, 'trade in the commodities market / commodities market volatility', '[{"en":"Oil and gold are among the most traded assets in the commodities market.","zh-TW":"石油和黃金是大宗商品市場中交易最頻繁的資產之一。"},{"en":"Commodities market prices affect production costs across industries.","zh-TW":"大宗商品市場價格影響了各行業的生產成本。"}]', NULL, NULL, 5, 1275, NULL),
(1276, 'commodity', '/kəˈmɒdəti/', 'noun', '{"zh-TW":["商品；大宗物資"],"en":["a raw material or agricultural product that can be bought and sold"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mod","meaning":"measure/fit (衡量/適合)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"完全適合交易的物品，即「商品」。"}', 'commodity prices / commodity market / basic commodities', '[{"en":"Oil is one of the most traded commodities.","zh-TW":"石油是交易量最大的商品之一。"},{"en":"Commodity prices fluctuate based on supply and demand.","zh-TW":"商品價格根據供需波動。"}]', NULL, NULL, 3, 1276, 840),
(1277, 'commodity market', '/kəˈmɒdɪti ˈmɑːrkɪt/', 'noun', '{"zh-TW":["大宗商品市場"],"en":["a market where raw materials and primary products are traded"]}', NULL, 'trade on the commodity market / commodity market volatility', '[{"en":"Oil prices fell sharply on the commodity market yesterday.","zh-TW":"大宗商品市場的石油價格昨天大幅下跌。"},{"en":"Agricultural exporters are highly exposed to commodity market fluctuations.","zh-TW":"農業出口商對大宗商品市場波動的敞口很高。"}]', NULL, NULL, 5, 1277, NULL),
(1278, 'commodity price', '/kəˈmɒdɪti praɪs/', 'noun', '{"zh-TW":["大宗商品價格"],"en":["the market price for a raw material or primary product"]}', NULL, 'falling commodity prices / commodity price volatility', '[{"en":"Rising commodity prices squeezed profit margins across the industry.","zh-TW":"大宗商品價格上漲壓縮了整個行業的利潤率。"},{"en":"The budget was revised after a sharp drop in commodity prices.","zh-TW":"大宗商品價格急劇下跌後，預算進行了修訂。"}]', NULL, NULL, 5, 1278, NULL),
(1279, 'commodity trading', '/kəˈmɒdɪti ˈtreɪdɪŋ/', 'noun', '{"zh-TW":["商品交易；大宗商品交易"],"en":["buying and selling raw materials such as metals, energy, and crops"]}', NULL, 'commodity trading firm / engage in commodity trading', '[{"en":"Commodity trading profits soared when oil prices surged.","zh-TW":"當油價飆升時，商品交易利潤大幅增加。"},{"en":"She joined a commodity trading desk specializing in agricultural products.","zh-TW":"她加入了專注於農業產品的商品交易部門。"}]', NULL, NULL, 5, 1279, NULL),
(1280, 'common', '/ˈkɒmən/', 'adjective', '{"zh-TW":["常見的；共同的"],"en":["happening often","shared by two or more","happening often; shared by all"]}', NULL, 'common ground / common sense; common sense / in common', '[{"en":"This is a common mistake.","zh-TW":"這是一個常見的錯誤。"},{"en":"We found common ground on the issue.","zh-TW":"我們在這個問題上找到了共識。"},{"en":"Colds are common in winter.","zh-TW":"感冒在冬天很常見。"},{"en":"We have a lot in common.","zh-TW":"我們有很多共同點。"}]', '{"adjective":"common","adverb":"commonly","noun":"commonality"}', NULL, 2, 1280, NULL),
(1281, 'common law', '/ˈkɒmən lɔː/', 'noun', '{"zh-TW":["普通法；習慣法"],"en":["law based on court decisions rather than written statutes"]}', NULL, 'under common law / common law system / common law principle', '[{"en":"Common law is the foundation of legal systems in England and many former colonies.","zh-TW":"普通法是英國和許多前殖民地法律體系的基礎。"},{"en":"Under common law, a contract requires offer, acceptance, and consideration.","zh-TW":"根據普通法，合約需要要約、承諾和對價。"}]', NULL, NULL, 4, 1281, NULL),
(1282, 'communicate', '/kəˈmjuːnɪkeɪt/', 'verb', '{"zh-TW":["溝通；傳達"],"en":["to share or exchange information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"munic","meaning":"share (分享)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起分享，即「溝通」。"}', 'communicate effectively / communicate with', '[{"en":"It''s important to communicate clearly with clients.","zh-TW":"與客戶清楚溝通很重要。"},{"en":"The change was communicated to all employees.","zh-TW":"變更已傳達給所有員工。"}]', '{"noun":"communication"}', NULL, 4, 1282, 293),
(1283, 'communication', 'kəˈmjuːnɪkeɪʃən', 'noun', '{"zh-TW":["溝通；通訊","交流"],"en":["the exchange of information","a way of sharing messages"]}', NULL, 'effective communication/open communication', '[{"en":"Effective communication is key to success.","zh-TW":"有效的溝通是成功的關鍵。"}]', '{"verb":"communicate","adjective":"communicative","adverb":"communicatively"}', NULL, 5, 1283, NULL),
(1284, 'communication skills', '/kəˌmjuːnɪˈkeɪʃən skɪlz/', 'noun', '{"zh-TW":["溝通技巧"],"en":["the ability to convey information clearly and effectively"]}', NULL, 'strong communication skills / written communication skills / verbal communication skills', '[{"en":"Excellent communication skills are essential for leadership roles.","zh-TW":"出色的溝通技巧對領導職位至關重要。"},{"en":"She was promoted in part due to her strong communication skills.","zh-TW":"她部分因其強大的溝通技巧而獲得晉升。"}]', '{"adjective":"communicative","verb":"communicate"}', NULL, 5, 1284, NULL),
(1285, 'communication strategy', '/''kəˌmjuːnɪˈkeɪʃən ˌstrætɪdʒi/', 'noun', '{"zh-TW":["溝通策略；傳播策略"],"en":["a plan that details how an organization will communicate with its various audiences"]}', NULL, 'develop a communication strategy / implement a communication strategy', '[{"en":"A clear communication strategy ensures consistent messaging across all departments.","zh-TW":"清晰的溝通策略確保所有部門的信息一致。"},{"en":"The team developed a crisis communication strategy to handle potential media issues.","zh-TW":"團隊制定了危機溝通策略，以處理潛在的媒體問題。"}]', NULL, NULL, 5, 1285, NULL),
(1286, 'communiqué', '/kəˈmjuːnɪkeɪ/', 'noun', '{"zh-TW":["公報；官方聲明"],"en":["an official announcement or statement, especially from a government or organization"]}', NULL, 'issue a communiqué / joint communiqué / press communiqué', '[{"en":"A joint communiqué was released after the trade summit.","zh-TW":"貿易峰會後發佈了聯合公報。"},{"en":"The communiqué outlined the agreed terms of the partnership.","zh-TW":"公報概述了夥伴關係的商定條款。"}]', NULL, NULL, 4, 1286, NULL),
(1287, 'community', '/kəˈmjuːnəti/', 'noun', '{"zh-TW":["社區；社群"],"en":["a group of people living in the same area or sharing characteristics"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mun","meaning":"service/duty (服務)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"一起服務的狀態，即「社區」。"}', 'local community / business community / online community', '[{"en":"The company supports the local community through donations.","zh-TW":"公司透過捐款支持當地社區。"},{"en":"The business community welcomed the new regulations.","zh-TW":"商業社群歡迎新法規。"}]', NULL, NULL, 3, 1287, NULL),
(1288, 'commute', '/kəˈmjuːt/', 'verb', '{"zh-TW":["通勤"],"en":["to travel regularly between home and work"]}', NULL, 'daily commute / commute by train', '[{"en":"She commutes to the office by subway every day.","zh-TW":"她每天搭地鐵上班。"},{"en":"The commute from the suburbs takes about an hour.","zh-TW":"從郊區通勤約需一小時。"}]', '{"noun":"commuter","adjective":"commutable"}', NULL, 3, 1288, NULL),
(1289, 'comorbidity', '/ˌkəʊmɔːˈbɪdɪti/', 'noun', '{"zh-TW":["共病；合併症"],"en":["the presence of two or more medical conditions in the same patient"]}', NULL, 'manage comorbidity / comorbidity risk / common comorbidity', '[{"en":"Obesity and hypertension are common comorbidities in diabetes patients.","zh-TW":"肥胖症和高血壓是糖尿病患者的常見共病。"},{"en":"Comorbidities complicate treatment planning and increase healthcare costs.","zh-TW":"共病使治療計劃複雜化並增加醫療成本。"}]', '{"adjective":"comorbid"}', NULL, 4, 1289, NULL),
(1290, 'company', '/ˈkʌmpəni/', 'noun', '{"zh-TW":["公司；企業"],"en":["a commercial business organization"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pan","meaning":"bread (麵包)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"一起吃麵包的人（夥伴），即「公司」。"}', 'company policy / parent company / run a company', '[{"en":"The company employs over 10,000 people worldwide.","zh-TW":"公司在全球僱用超過10,000人。"},{"en":"She started her own company at age 25.","zh-TW":"她25歲時創辦了自己的公司。"}]', NULL, NULL, 3, 1290, 294),
(1291, 'comparables', '/kəmˈpærəblz/', 'noun', '{"zh-TW":["可比公司；參考案例"],"en":["companies or transactions used as benchmarks for valuation or analysis"]}', NULL, 'identify comparables / trading comparables', '[{"en":"Analysts selected three comparables for the acquisition valuation.","zh-TW":"分析師為收購估值選擇了三個可比公司。"},{"en":"Comparables-based valuation adjusts for differences in size and growth rates.","zh-TW":"基於可比公司的估值對規模和增長率的差異進行了調整。"}]', '{"synonym":"comps"}', NULL, 4, 1291, NULL),
(1292, 'compare', '/kəmˈpeər/', 'verb', '{"zh-TW":["比較；對照","比較"],"en":["to examine similarities and differences between","to examine the similarities and differences","to estimate similarities or differences"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"par","meaning":"equal (相等)"},"logic":"放在一起看是否相等，即「比較」。"}', 'compare with/to / compare prices; compare with / compare to; compare with / compare to / compared to', '[{"en":"Let''s compare the two proposals side by side.","zh-TW":"讓我們並排比較兩份提案。"},{"en":"Compared to last year, sales have increased 20%.","zh-TW":"與去年相比，銷售增長了20%。"},{"en":"Compare these two products.","zh-TW":"比較這兩個產品。"},{"en":"Compared to last year, sales rose.","zh-TW":"與去年相比，銷售額上升了。"},{"en":"Compare these two products before buying.","zh-TW":"購買前先比較這兩個產品。"},{"en":"Compared to last year, sales are up 20%.","zh-TW":"與去年相比，銷售增長了20%。"}]', '{"noun":"comparison","adjective":"comparable","adjective2":"comparative"}', NULL, 3, 1292, 295),
(1293, 'comparison', 'kəmˈpærɪsən', 'noun', '{"zh-TW":["比較；對比","類比"],"en":["the act of comparing","a similarity or difference"]}', NULL, 'make a comparison/by comparison', '[{"en":"By comparison, our prices are lower.","zh-TW":"相比之下，我們的價格更低。"}]', '{"verb":"compare","adjective":"comparable","adverb":"comparably"}', NULL, 4, 1293, 525),
(1294, 'compass', '/''kʌmpəs/', 'noun', '{"zh-TW":["指南針；羅盤"],"en":["an instrument for finding direction, with a needle that points to magnetic north"]}', NULL, 'magnetic compass / read a compass / use a compass', '[{"en":"The hiker relied on a compass to find his way back to camp.","zh-TW":"徒步者依靠指南針找到回營地的路。"},{"en":"A compass is an essential tool for any serious trekker.","zh-TW":"指南針是任何認真徒步者的必備工具。"}]', NULL, NULL, 3, 1294, NULL),
(1295, 'compassion', '/kəmˈpæʃn/', 'noun', '{"zh-TW":["同情心；憐憫"],"en":["sympathy and concern for the sufferings of others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pass","meaning":"suffer (受苦)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"一起感受痛苦，即「同情」。"}', 'show compassion / have compassion for', '[{"en":"She showed great compassion for the homeless.","zh-TW":"她對無家可歸的人表現出極大的同情。"},{"en":"A good leader leads with compassion.","zh-TW":"好的領導者以同理心領導。"}]', '{"adjective":"compassionate"}', NULL, 4, 1295, NULL),
(1296, 'compatible', '/kəmˈpætəbl/', 'adjective', '{"zh-TW":["相容的；兼容的","相容的"],"en":["able to exist or work together without conflict","able to work together without problems"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pat","meaning":"suffer/feel (感受)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠一起感受的，即「相容的」。"}', 'compatible with / compatible systems; compatible with / backward compatible', '[{"en":"The new software is compatible with all devices.","zh-TW":"新軟體與所有裝置相容。"},{"en":"Make sure the parts are compatible before ordering.","zh-TW":"訂購前請確認零件相容。"},{"en":"Is this software compatible with Mac?","zh-TW":"這軟體和Mac相容嗎？"},{"en":"The new version is backward compatible.","zh-TW":"新版本向下相容。"}]', '{"noun":"compatibility"}', NULL, 4, 1296, NULL),
(1297, 'compel', '/kəmˈpel/', 'verb', '{"zh-TW":["強迫；迫使"],"en":["to force or oblige someone to do something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pel","meaning":"drive (驅使)"},"logic":"完全驅使，即「強迫」。"}', 'compel sb to do / feel compelled', '[{"en":"Economic pressures compelled the company to downsize.","zh-TW":"經濟壓力迫使公司裁員。"},{"en":"She felt compelled to report the safety violation.","zh-TW":"她覺得不得不舉報安全違規。"}]', '{"adjective":"compelling"}', NULL, 2, 1297, NULL),
(1298, 'compelling argument', '/''kəmˌpelɪŋ ˌɑːrɡjumənt/', 'noun', '{"zh-TW":["有力的論點；令人信服的論點"],"en":["a strong and persuasive reason or set of reasons that is difficult to ignore or refute"]}', NULL, 'make a compelling argument / present a compelling argument / build a compelling argument', '[{"en":"She made a compelling argument for investing in renewable energy infrastructure.","zh-TW":"她提出了一個支持投資可再生能源基礎設施的有力論點。"},{"en":"The lawyer presented a compelling argument that swayed the jury in her favor.","zh-TW":"律師提出了一個令人信服的論點，使陪審團站到了她這邊。"}]', '{"verb":"compel","adjective":"compelling","adverb":"compellingly"}', NULL, 5, 1298, NULL),
(1299, 'compendium', '/kəmˈpendiəm/', 'noun', '{"zh-TW":["概要；彙編"],"en":["a collection of concise but detailed information about a particular subject"]}', NULL, 'publish a compendium / legal compendium / compendium of knowledge', '[{"en":"The library published a compendium of environmental regulations.","zh-TW":"圖書館出版了一本環境法規彙編。"},{"en":"The professor assigned a compendium of case studies as course reading material.","zh-TW":"教授指定了一本案例研究彙編作為課程閱讀材料。"}]', NULL, NULL, 4, 1299, NULL);